import csv
import json


def load_orders(path: str) -> list[dict]:
    """Load orders from a CSV file."""
    rows = []
    with open(path) as f:
        for row in csv.DictReader(f):
            rows.append(row)
    return rows


def total_by_customer(rows: list[dict]) -> dict[str, float]:
    """Calculate total amount per customer."""
    totals = {}
    for row in rows:
        name = row["customer"]
        amount = float(row["amount"])
        if name not in totals:
            totals[name] = 0.0
        totals[name] += amount
    return totals


def top_customers(totals: dict[str, float], n: int) -> list[tuple[str, float]]:
    """Get the top n customers by total amount."""
    items = sorted(totals.items(), key=lambda kv: kv[1], reverse=True)
    return items[:n]


def filter_by_status(rows: list[dict], status: str) -> list[dict]:
    """Filter rows by a specific status value."""
    out = []
    for row in rows:
        if row["status"] == status:
            out.append(row)
    return out


def average_order_value(rows: list[dict]) -> float:
    """Calculate the average order value from a list of rows."""
    if not rows:
        return 0.0
    total = 0.0
    for row in rows:
        total += float(row["amount"])
    return total / len(rows)


def save_report(path: str, totals: dict[str, float], top: list[tuple[str, float]]) -> None:
    """Save the report data to a JSON file."""
    report = {"totals": totals, "top": top}
    with open(path, "w") as f:
        json.dump(report, f, indent=2)


def main() -> None:
    """Main function to process orders and generate a report."""
    rows = load_orders("orders.csv")
    paid = filter_by_status(rows, "paid")
    totals = total_by_customer(paid)
    top = top_customers(totals, 5)
    print("average order value:", average_order_value(paid))
    save_report("report.json", totals, top)


if __name__ == "__main__":
    main()
